def a_snake(s):
    result = ""
    for i, c in enumerate(s):
        if c.isupper():
            if i > 0:
                result += "_"
            result += c.lower()
        else:
            result += c
    return result

def primos(n):
    if n < 2:
        return []
    sieve = [True] * (n + 1)
    sieve[0] = sieve[1] = False
    for i in range(2, int(n**0.5) + 1):
        if sieve[i]:
            for j in range(i*i, n + 1, i):
                sieve[j] = False
    return [i for i in range(2, n + 1) if sieve[i]]

