def fusionar(intervalos):
    if not intervalos:
        return []

    # Ordenar intervalos por inicio
    ordenados = sorted(intervalos)
    fusionados = [ordenados[0]]

    for actual in ordenados[1:]:
        ultimo = fusionados[-1]
        # Si se solapan o se tocan, fusionar
        if actual[0] <= ultimo[1]:
            fusionados[-1] = (ultimo[0], max(ultimo[1], actual[1]))
        else:
            fusionados.append(actual)

    return fusionados

