def mediana(nums):
    if not nums:
        return None
    nums_ordenados = sorted(nums)
    n = len(nums_ordenados)
    if n % 2 == 1:
        return nums_ordenados[n // 2]
    else:
        return (nums_ordenados[n // 2 - 1] + nums_ordenados[n // 2]) / 2

