def distancia(a, b):
    m, n = len(a), len(b)
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(m + 1):
        dp[i][0] = i
    for j in range(n + 1):
        dp[0][j] = j

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i - 1] == b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = 1 + min(
                    dp[i - 1][j],    # borrado
                    dp[i][j - 1],    # inserción
                    dp[i - 1][j - 1] # sustitución
                )

    return dp[m][n]

def a_base(n, base):
    if n == 0:
        return '0'
    digits = '0123456789abcdef'
    result = ''
    while n > 0:
        result = digits[n % base] + result
        n //= base
    return result

def interseccion(a, b):
    resultado = []
    i = j = 0
    while i < len(a) and j < len(b):
        if a[i] == b[j]:
            if not resultado or resultado[-1] != a[i]:
                resultado.append(a[i])
            i += 1
            j += 1
        elif a[i] < b[j]:
            i += 1
        else:
            j += 1
    return resultado

