def sumar_romanos(a, b):
    valores = {
        'I': 1, 'V': 5, 'X': 10, 'L': 50,
        'C': 100, 'D': 500, 'M': 1000
    }

    def romano_a_entero(romano):
        resultado = 0
        i = 0
        while i < len(romano):
            if i + 1 < len(romano) and valores[romano[i]] < valores[romano[i + 1]]:
                resultado += valores[romano[i + 1]] - valores[romano[i]]
                i += 2
            else:
                resultado += valores[romano[i]]
                i += 1
        return resultado

    def entero_a_romano(num):
        valores = [
            (1000, 'M'), (900, 'CM'), (500, 'D'), (400, 'CD'),
            (100, 'C'), (90, 'XC'), (50, 'L'), (40, 'XL'),
            (10, 'X'), (9, 'IX'), (5, 'V'), (4, 'IV'), (1, 'I')
        ]
        resultado = ''
        for valor, simbolo in valores:
            count = num // valor
            resultado += simbolo * count
            num -= valor * count
        return resultado

    suma = romano_a_entero(a) + romano_a_entero(b)
    return entero_a_romano(suma)

